text:
{
  "title": "大都市地域における特別区の設置に関する法律の改正案",
  "lead": {
    "es": "とくべつくを つくるか きめる じゅうみんとうひょうと、ちほうの せんきょの きかんが かさならないように する ほうりつあん です。",
    "hs": "特別区をつくるかを決める住民投票の期間と、地方の議会や首長（知事・市長など）の選挙の期間が重ならないようにすることを求める法律案です。",
    "std": "特別区の設置についての住民投票の期間と、関係する市町村・道府県の議会議員選挙や首長選挙の期間が重ならないようにすることを定めようとした法律案。",
    "univ": "特別区の設置についての住民投票の期日の告示の日から当該期日までの期間と、特定選挙の期日の告示の日から当該期日までの期間とが重複しないようにすることを内容とする法律案。"
  },
  "facts": [
    {
      "es": "じゅうみんとうひょうの きかんと、しや どうふけんの ぎかいの せんきょや ちょう（ちじ・しちょう など）の せんきょの きかんが、かさならないように するとしていた。こまかい ことは「せいれい」（ないかくが きめる きまり）で きめるとしていた。※ただしくは「告示の日から期日までの期間」どうしが重複してはならない、という内容。",
      "hs": "住民投票の期間と、関係する市町村・道府県の議会議員の選挙や首長の選挙（「特定選挙」）の期間が重ならないようにし、そのために必要なことは政令（内閣が決めるきまり）で決めるとしていた。※期間は、それぞれ告示の日から投票日（期日）までのこと。",
      "std": "住民投票の期日の告示の日から期日までの期間と、関係市町村・関係道府県の議会議員の一般選挙と長の選挙（特定選挙）の告示の日から期日までの期間が重複しないようにし、必要な事項は政令で定めるとしていた。",
      "univ": "特別区の設置についての住民投票の期日の告示の日から当該期日までの期間と関係市町村及び関係道府県の議会の議員の一般選挙及び長の選挙（特定選挙）の期日の告示の日から当該期日までの期間とは、重複してはならないものとし、そのために必要な事項は、政令で定めるとしていた。"
    },
    {
      "es": "その きまりは、せんきょが きめられた きかんの なかで かならず おこなわれ、じゅうみんとうひょうも できるだけ きめられた きかんの なかで おこなわれるように するとしていた。",
      "hs": "その政令は、特定選挙が公職選挙法で決められた期間の中で必ず行われ、住民投票もできるだけ決められた期間の中で行われるように定めるとしていた。",
      "std": "その政令は、特定選挙が公職選挙法の規定により選挙を行うべき期間内に必ず行われ、住民投票ができる限り住民投票を行うべき期間内に行われるよう定めるとしていた。",
      "univ": "一の政令は、特定選挙が公職選挙法の規定により選挙を行うべき期間内に必ず行われ、かつ、特別区の設置についての住民投票ができる限り住民投票を行うべき期間内に行われるよう定めるとしていた。"
    },
    {
      "es": "できていれば、きまってから 3か月いないの、せいれいで きめる ひから つかわれる よていだった。※ただしくは「公布日から起算して3箇月以内で政令で定める日」。",
      "hs": "成立していれば、公布（国が知らせること）の日から3か月以内で政令で決める日から使われる内容だった。",
      "std": "成立していれば、公布日から起算して3箇月以内で政令で定める日から施行する内容だった。",
      "univ": "成立していれば、公布日から起算して3箇月以内で政令で定める日から施行する内容だった。"
    }
  ]
}
